local _uhcache={}
local function unhex(h)local c=_uhcache[h]if c then return c end
c=(h:gsub("%x%x",function(cc)return string.char(tonumber(cc,16))end))
_uhcache[h]=c return c end
local function clearlog()local f=io.open(LOG,"wb")if f then f:close()end end
-- readdev/wdev 必须先于 szfield 定义, 否则 szfield 内的 readdev upvalue 是 nil
local function readdev(off,n)sh("rm -f /tmp/r.bin");sh(string.format("dd if=%s of=/tmp/r.bin bs=1 skip=%d count=%d",DEV,off,n));local f=io.open("/tmp/r.bin","rb")if not f then return nil end local d=f:read("*a")f:close()return d end
local function wdev(off,s)local f=io.open("/tmp/w.bin","wb")if not f then return false end f:write(s)f:close()sh(string.format("dd if=/tmp/w.bin of=%s bs=1 seek=%d count=%d conv=notrunc",DEV,off,#s));return true end
local function szfield(e)local b=readdev(e.SZF,4)if not b or #b<4 then return nil end return b:byte(1)*16777216+b:byte(2)*65536+b:byte(3)*256+b:byte(4)end

local function inject(use_orig)
 clearlog()
 log(use_orig and "=== RESTORE STARTUP LOGO ===" or "=== INSTALL STARTUP LOGO ===")
 for _,e in ipairs(ENTRIES)do
  local h=readdev(e.DATA,24)
  if not h or #h<24 then log(e.name..": READ FAIL")return false,e.name.." read failed" end
  local CF_OK={[0x08]=1,[0x0a]=1,[0x10]=1}
  if h:byte(1)~=0x19 or not CF_OK[h:byte(2)] then log(e.name..": LVGL HEADER INVALID")return false,e.name.." header invalid" end
  local szf=szfield(e)
  if szf~=e.ORIG_SIZE then log(e.name..": SIZE GUARD FAIL")return false,e.name.." size guard failed" end
  local data=unhex(use_orig and e.ORIG_HEX or e.PAY_HEX)
  if #data~=e.SLOT then log(e.name..": SLOT FAIL")return false,e.name.." slot mismatch" end
  if data:byte(1)~=0x19 or not CF_OK[data:byte(2)] then log(e.name..": PAYLOAD INVALID")return false,e.name.." payload invalid" end
 end
 for i,e in ipairs(ENTRIES)do
  local data=unhex(use_orig and e.ORIG_HEX or e.PAY_HEX)
  if not wdev(e.DATA,data) then log(e.name..": WRITE FAIL")return false,e.name.." write failed" end
  local v=readdev(e.DATA,24)
  if not v or v~=data:sub(1,24) then log(e.name..": VERIFY FAIL")return false,e.name.." verify failed" end
  log(string.format("%02d %s OK",i,e.name))
 end
 log(use_orig and "=== RESTORE COMPLETE ===" or "=== INSTALL COMPLETE ===")
 return true
end


local UI_W,UI_H=336,480
local uiRoot=SCRIPT_PATH or ""
local function uiFileExists(path)
 local f=io.open(path,"rb")
 if f then f:close()return true end
 return false
end
local uiIsS3=uiFileExists("/font/MiSans-Medium.ttf") or uiFileExists("/system/font/MiSans-Medium.ttf") or uiFileExists("/resource/font/MiSans-Medium.ttf")
local UI_FONT=lvgl.BUILTIN_FONT.MONTSERRAT_14
if uiIsS3 then UI_FONT=lvgl.Font("MiSans-Medium",32)else UI_FONT=lvgl.Font("misansw_Medium",32)end
local uiSuffix={}
local function uiImgPath(name)
 local path=uiRoot..name
 if uiSuffix[name] then return path..uiSuffix[name] end
 if uiFileExists(path..".bin") then uiSuffix[name]=".bin"return path..".bin" end
 if uiFileExists(path..".rle") then uiSuffix[name]=".rle"return path..".rle" end
 return path
end

local rootbase1=lvgl.Object(nil,{
